/**
 * Cloudflare Worker entry (see wrangler.jsonc). Wraps the OpenNext-generated
 * fetch handler and adds the scheduled step runner: the durable job queue in
 * Postgres is drained once a minute, with leases making it safe to run
 * alongside the request-time kick in `src/server/worker/kick.ts`.
 */
// @ts-expect-error generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

type Env = { DATABASE_URL?: string } & Record<string, string | undefined>;
// Minimal runtime types so the project does not need the global Workers type package.
type ScheduledEvent = { scheduledTime: number; cron: string };
type ExecutionContext = { waitUntil(p: Promise<unknown>): void; passThroughOnException(): void };
type ExportedHandler<E> = {
  fetch?: (req: Request, env: E, ctx: ExecutionContext) => Promise<Response> | Response;
  scheduled?: (event: ScheduledEvent, env: E, ctx: ExecutionContext) => Promise<void> | void;
};

export default {
  fetch: handler.fetch,
  async scheduled(event: ScheduledEvent, env: Env, ctx: ExecutionContext) {
    // Bindings and vars are not on process.env inside the scheduled handler, so
    // the database handle is built here explicitly.
    for (const [k, v] of Object.entries(env)) if (typeof v === "string") process.env[k] = v;
    const { createDb } = await import("./src/server/db/client");
    const { drain } = await import("./src/server/worker/runner");
    if (!env.DATABASE_URL) throw new Error("DATABASE_URL secret is not set");
    const handle = await createDb({ driver: "neon", url: env.DATABASE_URL, migrate: false, poolSize: 2 });
    try {
      const n = await drain(handle.db, { workerId: `cron-${event.scheduledTime}`, maxJobs: 50 });
      if (n > 0) console.log(`[cron] processed ${n} job(s)`);
    } finally {
      ctx.waitUntil(handle.close());
    }
  },
} satisfies ExportedHandler<Env>;
